const ELEMENT_PROP_KEYS = new Set(["theme","label","value","rows","groupsPerRow","strokeWidth","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  label: "videos rendered on launch day",
  value: 1240,
  rows: 4,
  groupsPerRow: 9,
  strokeWidth: 9,
  stagger: 2,
  accent: "#3B5BFD",
  fontFamily: "Fraunces",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type TallyMarksElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof TallyMarksBase>;

const TallyMarksInner = forwardRef<
  HTMLDivElement,
  TallyMarksElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<TallyMarks>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <TallyMarksBase
          {...(componentProps as unknown as ComponentProps<typeof TallyMarksBase>)}
        />
      </div>
    </Sequence>
  );
});

export const TallyMarks = Interactive.withSchema({
  Component: TallyMarksInner,
  componentName: "<TallyMarks>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
